import re

def parse_version(v_str):
    if not isinstance(v_str, str):
        raise ValueError("Invalid version")
    m = re.match(r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$', v_str)
    if not m:
        raise ValueError(f"Invalid version: {v_str}")
    major_s, minor_s, patch_s = m.group(1), m.group(2), m.group(3)
    for s in (major_s, minor_s, patch_s):
        if len(s) > 1 and s[0] == '0':
            raise ValueError(f"Leading zero in version number: {s}")

    pre_str = m.group(4)
    if pre_str is not None:
        pre_ids = pre_str.split('.')
