                raise ValueError(f"Invalid prerelease identifier: {pid}")
            if pid.isdigit():
                if len(pid) > 1 and pid[0] == '0':
                    raise ValueError(f"Leading zero in numeric prerelease: {pid}")
            elif not re.match(r'^[0-9A-Za-z-]+$', pid):
                raise ValueError(f"Invalid prerelease identifier: {pid}")
    else:
        pre_ids = None
    return (int(major_s), int(minor_s), int(patch_s), pre_ids)

