def migrate(conn):
    if conn.execute("SELECT version FROM schema_version").fetchone()[0] == 2:
        return

    fk_enabled = conn.execute("PRAGMA foreign_keys").fetchone()[0]
    conn.execute("PRAGMA foreign_keys = OFF")

    def _to_cents(val):
        return int((Decimal(repr(val)) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))

    conn.create_function("_to_cents", 1, _to_cents)

    conn.execute("CREATE TABLE orders_new (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), amount_cents INTEGER NOT NULL)")
    conn.execute("INSERT INTO orders_new (id, customer_id, amount_cents) SELECT id, customer_id, _to_cents(amount) FROM orders")
    conn.execute("DROP TABLE orders")
    conn.execute("ALTER TABLE orders_new RENAME TO orders")
    conn.execute("CREATE INDEX idx_orders_customer ON orders(customer_id)")

    conn.execute("PRAGMA foreign_key_check")
    conn.execute("PRAGMA foreign_keys = ?", (fk_enabled,))
    conn.execute("UPDATE schema_version SET version = 2")
    conn.commit()
