    if len(fields) != 5:
        raise ValueError("Wrong number of fields")

    ranges = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]
    parsed = []
    unrestricted = []

    for i, f in enumerate(fields):
        min_v, max_v = ranges[i]
        values = set()
        is_unrestricted = (f == '*')
        for item in f.split(','):
            item = item.strip()
            if not item:
                raise ValueError("Empty item")
            step = 1
            if '/' in item:
                base, step_str = item.split('/', 1)
                if not step_str.isdigit() or int(step_str) < 1:
                    raise ValueError("Invalid step")
                step = int(step_str)
            else:
                base = item

            if base == '*':
                start, end = min_v, max_v
            elif '-' in base:
                parts = base.split('-', 1)
                if len(parts) != 2 or not parts[0].isdigit() or not parts[1].isdigit():
                    raise ValueError(f"Invalid range: {base}")
                start, end = int(parts[0]), int(parts[1])
                if start > end:
                    raise ValueError(f"A > B: {base}")
            elif base.isdigit():
                start, end = int(base), int(base)
            else:
                raise ValueError(f"Invalid item: {base}")

            if start < min_v or end > max_v:
                raise ValueError(f"Out of range: {base}")

            current_val = start
            while current_val <= max_v:
                if base == '*':
                    values.add(current_val)
                elif base.isdigit():
                    values.add(current_val)
                else:
                    if current_val <= end:
                        values.add(current_val)
                current_val += step
        parsed.append(sorted(values))
        unrestricted.append(is_unrestricted)

