            if i + 1 >= n:
                raise ValueError("Trailing lone backslash")
            matchers.append(('ESC', pat[i+1]))
            i += 2
        else:
            matchers.append(('LIT', c))
            i += 1
    return matchers

def match_segment(matchers, s):
    m = len(matchers)
    n = len(s)
    memo = {}
    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if i == m:
            res = j == n
            memo[(i, j)] = res
            return res

        op = matchers[i]
        if op[0] == 'STAR':
            for k in range(j, n + 1):
                if dp(i + 1, k):
                    memo[(i, j)] = True
                    return True
            memo[(i, j)] = False
            return False
        elif op[0] == 'ANY':
            if j < n:
                res = dp(i + 1, j + 1)
                memo[(i, j)] = res
                return res
            memo[(i, j)] = False
            return False
        elif op[0] == 'BRACKET':
            neg, chars = op[1], op[2]
            if j < n:
                c = s[j]
                in_set = c in chars
                if neg:
                    in_set = not in_set
                if in_set:
                    res = dp(i + 1, j + 1)
                    memo[(i, j)] = res
                    return res
            memo[(i, j)] = False
            return False
        elif op[0] == 'ESC':
            if j < n and s[j] == op[1]:
                res = dp(i + 1, j + 1)
                memo[(i, j)] = res
                return res
            memo[(i, j)] = False
            return False
        else: # LIT
            if j < n and s[j] == op[1]:
                res = dp(i + 1, j + 1)
                memo[(i, j)] = res
                return res
            memo[(i, j)] = False
            return False

    return dp(0, 0)
